use std :: collections :: HashMap ; fn handle (request : & str) -> String { let parsed = parse (request) ; let routed = route (parsed) ; format_response (routed) } fn parse (request : & str) -> HashMap < String , String > { let first_line = request . lines () . next () . unwrap_or ("") ; let words : Vec < & str > = first_line . split_whitespace () . collect () ; let mut conv = HashMap :: new () ; if let [method , path , _protocol @ ..] = & words [..] { conv . insert ("method" . to_string () , words [0] . to_string ()) ; conv . insert ("path" . to_string () , words [1] . to_string ()) ; } conv . insert ("resp_body" . to_string () , "" . to_string ()) ; conv } fn route (mut conv : HashMap < String , String >) -> HashMap < String , String > { conv . insert ("resp_body" . to_string () , "This is about us" . to_string ()) ; conv } fn format_response (conv : HashMap < String , String >) -> String { format ! ("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\n\r\n{}" , conv . get ("resp_body") . unwrap_or (& "" . to_string ()) . len () , conv . get ("resp_body") . unwrap_or (& "" . to_string ())) } fn main () { }